use std::fs::File;
use std::io::{self, Read};
use std::num::ParseIntError;

// ---- Functions that return Result ----

// ---- Without ? operator ----
fn read_file_manual() -> Result<String, io::Error> {
    let mut file = match File::open("hello.txt") {
        Ok(file) => file,
        Err(e) => return Err(e),
    };

    let mut contents = String::new();
    match file.read_to_string(&mut contents) {
        Ok(_) => Ok(contents),
        Err(e) => Err(e),
    }
}

// ---- With ? operator ----
fn read_file_question() -> Result<String, io::Error> {
    let mut file = File::open("hello.txt")?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    Ok(contents)
}

// ---- Chaining with ? ----
fn read_file_chained() -> Result<String, io::Error> {
    let mut contents = String::new();
    File::open("hello.txt")?.read_to_string(&mut contents)?;
    Ok(contents)
}

// ---- Parsing with ? ----
fn parse_number(s: &str) -> Result<i32, ParseIntError> {
    let num = s.parse()?;
    Ok(num)
}

// ---- Multiple operations with ? ----
fn process_numbers(a: &str, b: &str) -> Result<i32, ParseIntError> {
    let num1 = a.parse::<i32>()?;
    let num2 = b.parse::<i32>()?;
    Ok(num1 + num2)
}

// ---- Custom error type with ? ----
#[derive(Debug)]
enum GameError {
    Io(io::Error),
    Parse(ParseIntError),
}

impl From<io::Error> for GameError {
    fn from(err: io::Error) -> Self {
        GameError::Io(err)
    }
}

impl From<ParseIntError> for GameError {
    fn from(err: ParseIntError) -> Self {
        GameError::Parse(err)
    }
}

fn load_player_data() -> Result<String, GameError> {
    let mut file = File::open("player.txt")?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    Ok(contents)
}

fn parse_player_score() -> Result<i32, GameError> {
    let data = load_player_data()?;
    let score = data.trim().parse()?;
    Ok(score)
}

fn main() {
    // ---- Using ? in main (with main returning Result) ----
    match read_file_question() {
        Ok(contents) => println!("File contents: {}", contents),
        Err(e) => println!("Error: {}", e),
    }

    // ---- Parsing ----
    match parse_number("42") {
        Ok(num) => println!("Parsed: {}", num),
        Err(e) => println!("Parse error: {}", e),
    }

    match parse_number("abc") {
        Ok(num) => println!("Parsed: {}", num),
        Err(e) => println!("Parse error: {}", e),
    }

    // ---- Multiple operations ----
    match process_numbers("10", "20") {
        Ok(sum) => println!("Sum: {}", sum),
        Err(e) => println!("Error: {}", e),
    }

    // ---- Custom error type ----
    match parse_player_score() {
        Ok(score) => println!("Player score: {}", score),
        Err(e) => println!("Error: {:?}", e),
    }
}

// ---- main can return Result ----
fn main2() -> Result<(), io::Error> {
    let mut file = File::open("hello.txt")?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    println!("Contents: {}", contents);
    Ok(())
}

